mapper.select:
SELECT a.ID id, a.BIZ_ID bizId, a.NOTE note, CONCAT(a.DIR_PATH, "/", a.FILE_NAME, ".", a.FILE_FORMAT) picUrl, a.FILE_SIZE picSize, a.BIZ_TIME bizTime, if(c.over_pic_id = a.ID, 1, 0) overImage, a.DEVICE_ID deviceId, a.CHANNEL_ID channelId FROM GMV_FILE_INFO a inner join GMV_DEVICE_CHANNEL c on a.DEVICE_ID = c.DEVICE_ID and a.CHANNEL_ID = c.CHANNEL_ID WHERE a.DEVICE_ID = #{deviceId,jdbcType=VARCHAR} AND a.CHANNEL_ID = #{channelId,jdbcType=VARCHAR} AND a.IS_DEL = 0 AND a.FILE_TYPE = 0
AND a.BIZ_TIME >= #{startTime,jdbcType=TIMESTAMP}
AND a.BIZ_TIME < #{endTime,jdbcType=TIMESTAMP}
ORDER BY a.ID DESC

SELECT COUNT(*)
FROM GMV_RECORD
WHERE STATE = 0
  and DEVICE_ID = #{deviceId,jdbcType=VARCHAR}
  AND CHANNEL_ID = #{channelId,jdbcType=VARCHAR}

SELECT TENANT_ID
from GMV_DEVICE
where DEVICE_ID = #{deviceId,jdbcType=VARCHAR}
